     "@media (min-width: 981px) { &::after { content: ''; position: absolute; z-index: -1; top: 4%; right: -2%; bottom: 2%; left: -4%; pointer-events: none; background: radial-gradient(38% 34% at 22% 30%, rgba(91,59,234,0.55), rgba(91,59,234,0) 100%), radial-gradient(34% 30% at 80% 28%, rgba(196,181,253,0.7), rgba(196,181,253,0) 100%), radial-gradient(40% 36% at 70% 78%, rgba(255,138,91,0.62), rgba(255,138,91,0) 100%), radial-gradient(30% 28% at 20% 80%, rgba(255,209,191,0.7), rgba(255,209,191,0) 100%); filter: blur(18px); } & > .e-con { animation: rl-flotte 8s ease-in-out infinite; } "
