MEDIAS = {'--mobile': '(max-width: 767px)', '--tablet': '(max-width: 1024px)'}


def blocs(css):
    """Découpe un CSS de classe (déclarations + règles « & … { } » + @media) en (prélude, corps), corps None = déclaration."""
    sortie, i, n, debut = [], 0, len(css), 0
    while i < n:
        c = css[i]
        if c == ';':
            sortie.append((css[debut:i].strip(), None))
            debut = i + 1
        elif c == '{':
            prelude, profondeur, j = css[debut:i].strip(), 1, i + 1
            while profondeur:
                profondeur += {'{': 1, '}': -1}.get(css[j], 0)
                j += 1
            sortie.append((prelude, css[i + 1:j - 1]))
            i, debut = j, j
            continue
        i += 1
    return sortie


def deplier(css, racine):
    """CSS imbriqué d'une classe → CSS à plat, « & » remplacé par la racine (déclarations de base ignorées)."""
    lignes = []
    for prelude, corps in blocs(css):
        if corps is None:
            continue
        if prelude.startswith('@media'):
            requete = prelude[6:].strip().strip('()')
            lignes.append('@media %s {\n%s\n}' % (MEDIAS.get(requete, '(' + requete + ')'), deplier(corps, racine)))
        else:
            selecteurs = ', '.join(x.strip().replace('&', racine) if '&' in x else racine + ' ' + x.strip() for x in prelude.split(','))
            lignes.append('%s { %s }' % (selecteurs, corps.strip()))
    return '\n'.join(lignes)


def feuille_editeur():
    """Aperçu des articles dans l'éditeur WordPress : polices + règles de la classe article-texte (dépliées)."""
    css = next(c for l, d, c in CLASSES if l == 'article-texte')
    polices = [l for l in open(os.path.join(ICI, '..', 'theme', 'rolling', 'assets', 'css', 'rolling.css'), encoding='utf8') if l.startswith('@font-face')]
    racine = '.is-root-container'
    extra = """
/* Éditeur seulement : sur le site, coches et chiffres en verre sont posés par le widget « Texte de l'article ». */
body { --paragraphe: #4A4858; --encre: #0F0F12; --legende: #6E6B7B; --violet: #5B3BEA; font-family: "Hanken Grotesk", system-ui, sans-serif; color: #0F0F12; background: #FAF9F7; }
.is-root-container > p, .is-root-container > ul, .is-root-container > ol { font-family: "Hanken Grotesk"; font-size: 18px; line-height: 1.7; color: #4A4858; }
.is-root-container > h2 { font-family: "Bricolage Grotesque"; font-weight: 650; font-size: 34px; line-height: 1.15; letter-spacing: -0.04em; }
.is-root-container > h3 { font-family: "Bricolage Grotesque"; font-weight: 650; font-size: 23px; letter-spacing: -0.035em; }
.is-root-container .is-style-coches { list-style: none; padding: 0; }
.is-root-container .is-style-coches > li { position: relative; padding-left: 38px; margin-top: 12px; }
.is-root-container .is-style-coches > li::before { content: ''; position: absolute; top: 2px; left: 0; width: 26px; height: 26px; background: url(../medias/coche-verre.png) center / contain no-repeat; }
.is-root-container .rl-chiffre-valeur { font-family: "Bricolage Grotesque"; font-weight: 800; font-size: 56px; line-height: 1; color: #8E4DE6; }
"""
    contenu = '/* Fichier généré par outils/classes_fiches.py : ne pas modifier à la main. */\n' + ''.join(polices) + extra + deplier(css, racine) + '\n'
    open(os.path.join(ICI, '..', 'theme', 'rolling', 'assets', 'css', 'rolling-article-editeur.css'), 'w', encoding='utf8').write(contenu)


def main():
    chemin = os.path.join(ICI, 'source', 'classes.json')
    d = json.load(open(chemin, encoding='utf8'))
    d['groupes'] = [g for g in d['groupes'] if g.get('nom') != 'Fiches et listes']
    existants = {c['label'] for g in d['groupes'] for c in g['classes']}
    doublons = [c[0] for c in CLASSES if c[0] in existants]
    if doublons:
        raise SystemExit('Classes déjà définies ailleurs : ' + ', '.join(doublons))
    d['groupes'].append({'nom': 'Fiches et listes', 'classes': [dict({'label': c[0], 'description': c[1], 'css': c[2]}, **({'brut': c[3]} if len(c) > 3 else {})) for c in CLASSES]})
    json.dump(d, open(chemin, 'w', encoding='utf8'), ensure_ascii=False, indent=1)
    print(len(CLASSES), 'classes dans « Fiches et listes »')
    feuille_editeur()


if __name__ == '__main__':
    main()
